func execLookPath(file string) (string, error) {
 // Search PATH
 pathEnv := os.Getenv("PATH")
 for _, dir := range strings.Split(pathEnv, ":") {
  full := filepath.Join(dir, file)
  if _, err := os.Stat(full); err == nil {
   return full, nil
  }
 }
 return "", fmt.Errorf("not found")
}

