func encryptToRecipients(plaintext []byte, recipients []interface{}) ([]byte, error) {
 // Generate file key 16 bytes random
 fk := make([]byte, 16)
 _, err := rand.Read(fk)
 if err != nil {
  return nil, err
 }

 // For each recipient, create stanza
 var stanzas [][]byte // each stanza is []byte of header lines for that recipient

