  switch r := rec.(type) {
  case []byte:
   // X25519 recipient (32 bytes)
   if len(r) != 32 {
    return nil, fmt.Errorf("invalid recipient at index %d", idx)
   }
   // Generate ephemeral key pair
   ephPriv := make([]byte, 32)
   _, err := rand.Read(ephPriv)
   if err != nil {
    return nil, err
   }
   ephPub, err := curve25519.X25519(ephPriv, curve25519.Basepoint)
   if err != nil {
    return nil, err
   }
   shared, err := curve25519.X25519(ephPriv, r)
   if err != nil {
    return nil, err
   }
   salt := append(ephPub, r...)
   prk := hkdfExtract(salt, shared)
   encKey := hkdfExpand(prk, []byte("age-encryption.org/v1/X25519"), 32)
