}

func convertBits5(data []byte, fromBits, toBits int, pad bool) []int {
 acc := 0
 bits := 0
 var ret []int
 maxv := (1 << toBits) - 1
 for _, value := range data {
  acc = (acc << fromBits) | int(value)
  bits += fromBits
  for bits >= toBits {
   bits -= toBits
   ret = append(ret, (acc>>bits)&maxv)
  }
 }
 if pad && bits > 0 {
  ret = append(ret, (acc<<(toBits-bits))&maxv)
 }
 return ret
}

