 var b64Lines []string
 inBody := false
 for _, line := range lines {
  if strings.Contains(line, "BEGIN AGE ENCRYPTED FILE") {
   inBody = true
   continue
  }
  if strings.Contains(line, "END AGE ENCRYPTED FILE") {
   break
  }
  if inBody {
   b64Lines = append(b64Lines, strings.TrimSpace(line))
  }
 }
 if !inBody {
  return nil, fmt.Errorf("failed to parse armor")
 }
 b64Str := strings.Join(b64Lines, "")
 // The armor uses strict base64 without padding? Actually age armor uses strict base64 (standard alphabet, no padding? Or with padding? Let's check)
 // Our earlier armor example: lines of base64 with no padding? The armor we saw had base64 lines that ended with "="? Let's check: earlier armor output ended with "="? It had "BHg=" at end, so includes padding.
 // So use StdEncoding
 decoded, err := base64.StdEncoding.DecodeString(b64Str)
 if err != nil {
  // Try RawStdEncoding
  decoded, err = base64.RawStdEncoding.DecodeString(b64Str)
  if err != nil {
   return nil, err
  }
 }
 return decoded, nil
}

func encodeArmor(data []byte) []byte {
 var buf bytes.Buffer
 buf.WriteString("-----BEGIN AGE ENCRYPTED FILE-----\n")
 b64Str := base64.StdEncoding.EncodeToString(data)
 // Split into 64-char lines
 for i:=0; i<len(b64Str); i+=64 {
  end := i+64
  if end > len(b64Str) {
   end = len(b64Str)
  }
  buf.WriteString(b64Str[i:end] + "\n")
 }
 buf.WriteString("-----END AGE ENCRYPTED FILE-----\n")
 return buf.Bytes()
}

