func readPassphrase(prompt string, confirm bool) (string, error) {
 // If stdin is not a terminal and /dev/tty not available, error
 // Try to open /dev/tty
 tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
 if err != nil {
  return "", fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %v", err)
 }
 defer tty.Close()

 // Check if stdin is terminal? Use term.IsTerminal
 // For simplicity, if fd 0 is not terminal, we still try /dev/tty

 // Print prompt to tty's stderr? Original prints to stderr
 fmt.Fprintf(os.Stderr, "%s", prompt)

 // Read line from tty
 reader := bufio.NewReader(tty)
 pass, err := reader.ReadString('\n')
 if err != nil {
  return "", err
 }
 pass = strings.TrimRight(pass, "\r\n")

 if confirm {
  fmt.Fprintf(os.Stderr, "Confirm passphrase: ")
  confirmPass, err := reader.ReadString('\n')
  if err != nil {
   return "", err
  }
  confirmPass = strings.TrimRight(confirmPass, "\r\n")
  if pass != confirmPass {
   return "", fmt.Errorf("passphrases didn't match")
  }
 }

 // If empty, autogenerate?
 if pass == "" {
  // Generate random passphrase via word list? For simplicity, we can generate a random string of 4 words? But original uses word list.
  // For our implementation, we can generate a simple random passphrase and print to stderr as original does: "Using the autogenerated passphrase \"...\""
  // The word list for age is from some list. We can approximate with random words.

  // Generate 10 random lowercase letters? But original uses hyphen separated words.

  // Let's generate 10 words from a small list? We can use a list of words embedded.

  words := []string{"release", "response", "step", "brand", "wrap", "ankle", "pair", "unusual", "sword", "train", "release", "response", "step", "brand", "wrap", "ankle", "pair", "unusual", "sword", "train"}
  // Actually need random
  var generated []string
  for i:=0;i<10;i++{
   idx := 0
   // random index
   b := make([]byte,1)
   rand.Read(b)
   idx = int(b[0]) % len(words)
   generated = append(generated, words[idx])
  }
  pass = strings.Join(generated, "-")
  fmt.Fprintf(os.Stderr, "Using the autogenerated passphrase %q.\n", pass)
 }

