// Recipient file reading

func readRecipientsFile(path string) ([]interface{}, error) {
 var data []byte
 var err error
 if path == "-" {
  data, err = io.ReadAll(os.Stdin)
  if err != nil {
   return nil, fmt.Errorf("failed to read %q: %v", path, err)
  }
 } else {
  data, err = os.ReadFile(path)
  if err != nil {
   return nil, fmt.Errorf("failed to open file: %v", err)
  }
 }

 var recipients []interface{}
 scanner := bufio.NewScanner(bytes.NewReader(data))
 lineNum := 0
 for scanner.Scan() {
  lineNum++
  line := strings.TrimSpace(scanner.Text())
  if line == "" || strings.HasPrefix(line, "#") {
   continue
  }
  rec, warning, err := parseRecipient(line)
  if warning != "" {
   fmt.Fprintf(os.Stderr, "age: warning: recipients file %q: %s at line %d\n", path, warning, lineNum)
   continue
  }
  if err != nil {
   // If file contains only unsupported keys, return "no recipients found"
   // For simplicity, if error is unknown type or malformed, return error with file context
   if strings.Contains(err.Error(), "unknown recipient type") || strings.Contains(err.Error(), "malformed") || strings.Contains(err.Error(), "invalid recipient") {
    // For recipient files, unsupported SSH keys are ignored with warning, not error
    // But for malformed recipient, return error
    return nil, fmt.Errorf("failed to parse recipient file %q: %q: %v", path, path, err)
   }
   return nil, fmt.Errorf("failed to parse recipient file %q: %q: %v", path, path, err)
  }
  recipients = append(recipients, rec)
 }

 // After reading, if no recipients, error
 if len(recipients) == 0 {
  // Check if there were warnings? If file contained only unsupported SSH keys, we already warned, but still no recipients
  // Return error "no recipients found"
  // Need to differentiate: For file with only unsupported SSH keys, we warned for each, then error "no recipients found"
  // For file with no valid recipients, same.

  // Check if file had any lines that were unsupported SSH keys? Our parseRecipient for SSH returns valid for supported keys, warning for unsupported? We need to handle warning for unsupported SSH keys.

  // For simplicity, return "no recipients found"
  return nil, fmt.Errorf("failed to parse recipient file %q: %q: no recipients found", path, path)
 }

 return recipients, nil
}

