func decodeArmor(data []byte) ([]byte, error) {
	s := string(data)
	lines := strings.Split(s, "\n")
	var b64Lines []string
	inBody := false
	for _, line := range lines {
		if strings.Contains(line, "BEGIN AGE ENCRYPTED FILE") {
			inBody = true
