// Bech32 charset
const charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

func bech32Polymod(values []int) int {
	gen := []int{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	chk := 1
	for _, v := range values {
		b := chk >> 25
		chk = (chk & 0x1ffffff) << 5 ^ v
		for i := 0; i < 5; i++ {
			if ((b >> i) & 1) == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}

func bech32HrpExpand(hrp string) []int {
	var ret []int
	for _, c := range hrp {
		ret = append(ret, int(c>>5))
	}
	ret = append(ret, 0)
	for _, c := range hrp {
		ret = append(ret, int(c&31))
	}
	return ret
}

func bech32CreateChecksum(hrp string, data []int) []int {
	values := append(bech32HrpExpand(hrp), data...)
	pm := bech32Polymod(append(values, []int{0, 0, 0, 0, 0, 0}...)) ^ 1
	var ret []int
	for i := 0; i < 6; i++ {
		ret = append(ret, (pm>>5*(5-i))&31)
	}
	return ret
}

func bech32Decode(s string) (hrp string, data []int, errMsg string) {
	hasLower := false
	hasUpper := false
	for _, c := range s {
		if c >= 'a' && c <= 'z' {
			hasLower = true
		} else if c >= 'A' && c <= 'Z' {
			hasUpper = true
		}
	}
	if hasLower && hasUpper {
		return "", nil, "mixed case"
	}
	lower := strings.ToLower(s)
	pos := strings.LastIndex(lower, "1")
	if pos < 1 {
		return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	if len(lower)-pos-1 < 6 {
		return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	dataPart := lower[pos+1:]
	// Check for '1' inside data part
	for i, c := range dataPart {
		if c == '1' {
			return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos+1+i, len(s))
		}
		if !strings.ContainsRune(charset, c) {
			return "", nil, fmt.Sprintf("invalid character data part: s[%d]=%d", i, c)
		}
	}
	var vals []int
	for _, c := range dataPart {
		vals = append(vals, strings.IndexRune(charset, c))
	}
	if bech32Polymod(append(bech32HrpExpand(lower[:pos]), vals...)) != 1 {
		return "", nil, "invalid checksum"
	}
	hrp = lower[:pos]
	data = vals[:len(vals)-6]
	return hrp, data, ""
}

func convertBits5to8(data []int) ([]byte, error) {
	acc := 0
	bits := 0
	var ret []byte
	for _, v := range data {
		acc = (acc << 5) | v
		bits += 5
		for bits >= 8 {
			bits -= 8
			ret = append(ret, byte((acc>>bits)&0xff))
		}
	}
	return ret, nil
}

func convertBits8to5(data []byte) []int {
	acc := 0
	bits := 0
	var ret []int
	maxv := 31
	for _, b := range data {
		acc = (acc << 8) | int(b)
		bits += 8
		for bits >= 5 {
			bits -= 5
			ret = append(ret, (acc>>bits)&maxv)
		}
	}
	if bits > 0 {
		ret = append(ret, (acc<<(5-bits))&maxv)
	}
	return ret
}

func bech32Encode(hrp string, data []byte) string {
	data5 := convertBits8to5(data)
	checksum := bech32CreateChecksum(hrp, data5)
	combined := append(data5, checksum...)
	s := hrp + "1"
	for _, d := range combined {
		s += string(charset[d])
	}
	return s
}

func bech32EncodeUpper(hrp string, data []byte) string {
	// hrp like "AGE-SECRET-KEY-"
	lowerHrp := strings.ToLower(hrp)
	data5 := convertBits8to5(data)
	checksum := bech32CreateChecksum(lowerHrp, data5)
	combined := append(data5, checksum...)
	s := hrp
	for _, d := range combined {
		c := charset[d]
		// to upper
		if c >= 'a' && c <= 'z' {
			c = c - 32
		}
		s += string(rune(c))
	}
	return s
}

func hkdfExtract(salt, ikm []byte) []byte {
	if salt == nil {
		salt = make([]byte, 32)
	}
	mac := hmac.New(sha256.New, salt)
	mac.Write(ikm)
	return mac.Sum(nil)
}

func hkdfExpand(prk, info []byte, length int) []byte {
	r := hkdf.Expand(sha256.New, prk, string(info))
	out := make([]byte, length)
	io.ReadFull(r, out)
	return out
}

// Recipient types
type x25519Recipient struct {
	pub []byte // 32
	raw string
}

type sshRsaRecipient struct {
	pub *rsa.PublicKey
	tag string
	raw string // original line
}

type sshEd25519Recipient struct {
	xPub []byte // converted X25519 pub
	edPub []byte // raw ed25519 pub
	tag string
	raw string
}

type scryptRecipient struct {
	passphrase string
	salt []byte
	logN int
}

type pluginRecipient struct {
	name string
}

func parseRecipient(rec string) (interface{}, string, error) {
	// SSH
	if strings.HasPrefix(rec, "ssh-rsa ") || strings.HasPrefix(rec, "ssh-ed25519 ") {
		pub, _, _, _, err := ssh.ParseAuthorizedKey([]byte(rec))
		if err != nil {
			return nil, "", fmt.Errorf("malformed SSH recipient: %q: %v", rec, err)
		}
		// Compute tag
		blob := pub.Marshal()
		h := sha256.Sum256(blob)
		tag := base64.RawStdEncoding.EncodeToString(h[:4])

		switch pub.Type() {
		case "ssh-ed25519":
			// Extract raw ed25519 pub (last 32 bytes of blob)
			// Blob format: string "ssh-ed25519" + string 32-byte key
			// For simplicity, get last 32
			edRaw := blob[len(blob)-32:]
			xPub, err := ed25519PubToX25519(edRaw)
			if err != nil {
				// Unsupported
				return nil, fmt.Sprintf("ignoring unsupported SSH key of type %q", pub.Type()), nil
			}
			return sshEd25519Recipient{xPub: xPub, edPub: edRaw, tag: tag, raw: rec}, "", nil
		case "ssh-rsa":
			cryptoPub := pub.(ssh.CryptoPublicKey).CryptoPublicKey()
			rsaPub, ok := cryptoPub.(*rsa.PublicKey)
			if !ok {
				return nil, fmt.Sprintf("ignoring unsupported SSH key of type %q", pub.Type()), nil
			}
			if rsaPub.N.BitLen() < 2048 {
				return nil, fmt.Sprintf("ignoring unsupported SSH key of type %q", pub.Type()), nil
			}
			return sshRsaRecipient{pub: rsaPub, tag: tag, raw: rec}, "", nil
		default:
			return nil, fmt.Sprintf("ignoring unsupported SSH key of type %q", pub.Type()), nil
		}
	}

	// Age
	lower := strings.ToLower(rec)
	if strings.HasPrefix(lower, "age1") {
		hrp, data5, errMsg := bech32Decode(rec)
		if errMsg != "" {
			// Determine error type
			countOnes := strings.Count(lower, "1")
			if strings.Contains(errMsg, "separator '1' at invalid position") {
				if countOnes == 1 {
					return nil, "", fmt.Errorf("malformed recipient %q: %s", rec, errMsg)
				} else {
					// Check if tag
					if strings.HasPrefix(lower, "age1tag1") || strings.HasPrefix(lower, "age1tagpq1") {
						return nil, "", fmt.Errorf("malformed recipient %q: invalid recipient encoding: %s", rec, errMsg)
					}
					return nil, "", fmt.Errorf("invalid recipient encoding: %s", errMsg)
				}
			}
			if strings.Contains(errMsg, "invalid character") || strings.Contains(errMsg, "mixed case") {
				// Check if multiple ones -> invalid recipient encoding, else malformed
				if countOnes > 1 {
					if strings.HasPrefix(lower, "age1tag1") || strings.HasPrefix(lower, "age1tagpq1") {
						return nil, "", fmt.Errorf("malformed recipient %q: invalid recipient encoding: %s", rec, errMsg)
					}
					return nil, "", fmt.Errorf("invalid recipient encoding: %s", errMsg)
				}
				return nil, "", fmt.Errorf("malformed recipient %q: %s", rec, errMsg)
			}
			if errMsg == "invalid checksum" {
				if countOnes > 1 {
					if strings.HasPrefix(lower, "age1tag1") || strings.HasPrefix(lower, "age1tagpq1") {
						return nil, "", fmt.Errorf("malformed recipient %q: invalid recipient encoding: %s", rec, errMsg)
					}
					return nil, "", fmt.Errorf("invalid recipient encoding: %s", errMsg)
				}
				return nil, "", fmt.Errorf("malformed recipient %q: %s", rec, errMsg)
			}
			return nil, "", fmt.Errorf("malformed recipient %q: %s", rec, errMsg)
		}
		// Decoded
		data8, _ := convertBits5to8(data5)
		switch hrp {
		case "age":
			if len(data8) != 32 {
				return nil, "", fmt.Errorf("malformed recipient %q: invalid length", rec)
			}
			// Check if valid X25519 point? Use ecdh to check, but x/crypto allows any
			return x25519Recipient{pub: data8, raw: rec}, "", nil
		case "age1tag":
			// tag
			if len(data8) == 32 {
				return nil, "", fmt.Errorf("malformed recipient %q: invalid tag recipient public key size %d", rec, len(data8))
			}
			if len(data8) != 33 {
				return nil, "", fmt.Errorf("malformed recipient %q: invalid tag recipient public key size %d", rec, len(data8))
			}
			// Check valid P-256 point
			if data8[0] != 2 && data8[0] != 3 {
				return nil, "", fmt.Errorf("malformed recipient %q: invalid tag recipient public key: invalid P256 point encoding", rec)
			}
			return struct {
				typ string
				pub []byte
				raw string
			}{"tag", data8, rec}, "", nil
		case "age1tagpq":
			if len(data8) < 100 {
				return nil, "", fmt.Errorf("malformed recipient %q: invalid tagpq recipient public key: invalid public key size", rec)
			}
			return struct {
				typ string
				pub []byte
				raw string
			}{"tagpq", data8, rec}, "", nil
		case "age1pq":
			if len(data8) < 100 {
				return nil, "", fmt.Errorf("malformed recipient %q: invalid MLKEM768-X25519 public key", rec)
			}
			return struct {
				typ string
				pub []byte
				raw string
			}{"pq", data8, rec}, "", nil
		default:
			if strings.HasPrefix(hrp, "age1") {
				pluginName := hrp[4:]
				return pluginRecipient{name: pluginName}, "", nil
			}
			return nil, "", fmt.Errorf("unknown recipient type: %q", rec)
		}
	}

	return nil, "", fmt.Errorf("unknown recipient type: %q", rec)
}

func ed25519PubToX25519(edPub []byte) ([]byte, error) {
	if len(edPub) != 32 {
		return nil, fmt.Errorf("invalid ed25519 public key size")
	}
	yBytes := make([]byte, 32)
	copy(yBytes, edPub)
	yBytes[31] &= 0x7f
	// little-endian to big int
	y := new(big.Int)
	for i := 31; i >= 0; i-- {
		y.Lsh(y, 8)
		y.Add(y, big.NewInt(int64(yBytes[i])))
	}
	p, _ := new(big.Int).SetString("7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed", 16)
	one := big.NewInt(1)
	num := new(big.Int).Add(one, y)
	den := new(big.Int).Sub(one, y)
	den.Mod(den, p)
	inv := new(big.Int).ModInverse(den, p)
	if inv == nil {
		return nil, fmt.Errorf("invalid ed25519 public key")
	}
	u := new(big.Int).Mul(num, inv)
	u.Mod(u, p)
	// to little-endian 32 bytes
	uBytes := make([]byte, 32)
	be := u.Bytes()
	// Pad BE to 32
	bePadded := make([]byte, 32)
	copy(bePadded[32-len(be):], be)
	for i := 0; i < 32; i++ {
		uBytes[i] = bePadded[31-i]
	}
	return uBytes, nil
}

func readRecipientsFile(path string) ([]interface{}, error) {
	var data []byte
	var err error
	if path == "-" {
		// Check if stdin used for multiple purposes: caller checks
		data, err = io.ReadAll(os.Stdin)
		if err != nil {
			return nil, fmt.Errorf("failed to read %q: %v", path, err)
		}
	} else {
		data, err = os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("failed to open file: %v", err)
		}
	}
	var recipients []interface{}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	lineNum := 0
	hasValid := false
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		rec, warning, err := parseRecipient(line)
		if warning != "" {
			fmt.Fprintf(os.Stderr, "age: warning: recipients file %q: %s at line %d\n", path, warning, lineNum)
			continue
		}
		if err != nil {
			// For malformed, return error with file context
			// Original error: "failed to parse recipient file \"/path\": \"/path\": <err>"
			// But err already contains "malformed recipient ..." etc.
			// So wrap as: failed to parse recipient file "path": "path": <inner error without prefix?>
			// Our parseRecipient errors already contain "malformed recipient ..." or "unknown recipient type" etc.
			// For file, we need to produce: failed to parse recipient file "path": "path": <error>
			// Where <error> is the inner error message without the outer wrapper? Let's try to produce similar.

			// If err is "malformed recipient ..." or "unknown recipient type" etc, we should return that as inner.
			// Original second error message had file name quoted.

			// For simplicity, return error as: failed to parse recipient file "path": "path": <err>
			// But if err is "malformed SSH recipient: ...", then it should be "failed to parse recipient file ...: ...: malformed SSH recipient..."

			// We'll do:

			return nil, fmt.Errorf("failed to parse recipient file %q: %q: %v", path, path, err)
		}
		hasValid = true
		recipients = append(recipients, rec)
		_ = hasValid
	}
	if len(recipients) == 0 {
		return nil, fmt.Errorf("failed to parse recipient file %q: %q: no recipients found", path, path)
	}
	return recipients, nil
}

func identitiesToRecipients(idPath string) ([]interface{}, error) {
	ids, err := parseIdentityFile(idPath)
	if err != nil {
		return nil, err
	}
	var recs []interface{}
	for _, id := range ids {
		switch v := id.(type) {
		case []byte:
			pub, err := curve25519.X25519(v, curve25519.Basepoint)
			if err != nil {
				continue
			}
			recs = append(recs, x25519Recipient{pub: pub})
		case ssh.Signer:
			// For SSH signer, get public key
			recs = append(recs, v.PublicKey())
		case string:
			// raw SSH private key content? Probably not
		}
	}
	return recs, nil
}

func parseIdentityFile(path string) ([]interface{}, error) {
	var content []byte
	var err error
	if path == "-" {
		content, err = io.ReadAll(os.Stdin)
		if err != nil {
			return nil, fmt.Errorf("failed to read %q: %v", path, err)
		}
	} else {
		content, err = os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("failed to open file: %v", err)
		}
	}
	// Check if age encrypted file (armored or not)
	trimmed := bytes.TrimSpace(content)
	isArmor := bytes.Contains(trimmed, []byte("BEGIN AGE ENCRYPTED FILE"))
	var data []byte
	if isArmor {
		data, err = decodeArmor(trimmed)
		if err != nil {
			return nil, fmt.Errorf("failed to read %q: %v", path, err)
		}
	} else {
		// Check if starts with age-encryption.org/v1
		if bytes.HasPrefix(trimmed, []byte("age-encryption.org/v1")) {
			data = trimmed
		} else {
			data = content
		}
	}
	// If data is age file (has scrypt), try decrypt as identity file
	if bytes.HasPrefix(data, []byte("age-encryption.org/v1")) && bytes.Contains(data, []byte("-> scrypt ")) {
		decrypted, err := decryptIdentityFileAsAge(data, path)
		if err != nil {
			return nil, err
		}
		content = decrypted
	} else if isArmor || bytes.HasPrefix(data, []byte("age-encryption.org/v1")) {
		// If it's age file but not scrypt, it's not a valid identity file? Actually identity file could be passphrase encrypted age file, which is scrypt. If it's X25519 encrypted age file, it could contain identities as well? The man says identity files can be passphrase encrypted age files, containing identities one per line. So only scrypt files are allowed as identity files that are encrypted. X25519 encrypted files would not be valid as identity? But we can try to decrypt them as well with identities? This is recursive, but for simplicity, if data is age file and not scrypt, we will try to decrypt it using identities? That would be loop. For this benchmark, we will only handle scrypt identity files.

		// If data is age file and not scrypt, and we are trying to parse identity file that is age file, original would try to decrypt it as age file with identities? Actually identity files containing age encrypted file would be passphrase encrypted, so scrypt. So we already handled scrypt case.

		// For other age file types, treat as invalid? But we already handled scrypt.

		// So for non-scrypt age file, we should treat as unknown identity type? Let's not.
	}

	// If content contains BEGIN OPENSSH or BEGIN RSA etc, treat as SSH private key file
	if bytes.Contains(content, []byte("BEGIN")) {
		// Try to parse as SSH private key
		// Use ssh.ParsePrivateKey (handles unencrypted)
		signer, err := ssh.ParsePrivateKey(content)
		if err != nil {
			// If error contains "passphrase" or "encrypted", we need to prompt for password? But for identity file that is SSH key with password, original prompts only if identity matches file? Complex.

			// Try ParseRawPrivateKey
			_, err2 := ssh.ParseRawPrivateKey(content)
			if err2 != nil {
				// Try with passphrase? For now, return unknown identity type
				// But we should still return the raw content as identity that will be tried later? For simplicity, if parsing fails, return unknown identity type error

				// Check if file is encrypted SSH key
				if strings.Contains(err.Error(), "passphrase") || strings.Contains(err.Error(), "encrypted") {
					// For encrypted SSH key, we should still keep it as identity and later prompt for password when it matches

					// We'll return a special object that holds encrypted key

					return []interface{}{string(content)}, nil
				}

				// Otherwise unknown type
				// Return error as per original: error at line 1: unknown identity type or malformed

				// For SSH file that is not valid, original might say unknown identity type

				// For simplicity, if content contains BEGIN, treat as SSH key even if parsing fails, return as identity
				return []interface{}{string(content)}, nil
			}
		}
		return []interface{}{signer}, nil
	}

	// Otherwise, parse as list of age secret keys
	var identities []interface{}
	scanner := bufio.NewScanner(bytes.NewReader(content))
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "AGE-SECRET-KEY-1") {
			hrp, data5, errMsg := bech32Decode(line)
			if errMsg != "" {
				return nil, fmt.Errorf("failed to read %q: error at line %d: malformed secret key: %s", path, lineNum, errMsg)
			}
			if hrp != "age-secret-key-" {
				return nil, fmt.Errorf("failed to read %q: error at line %d: unknown identity type", path, lineNum)
			}
			data8, err := convertBits5to8(data5)
			if err != nil {
				return nil, fmt.Errorf("failed to read %q: error at line %d: %v", path, lineNum, err)
			}
			if len(data8) != 32 {
				return nil, fmt.Errorf("failed to read %q: error at line %d: invalid length", path, lineNum)
			}
			identities = append(identities, data8)
			continue
		}
		if strings.HasPrefix(line, "AGE-PLUGIN-") {
			_, _, errMsg := bech32Decode(line)
			if errMsg != "" {
				if strings.Contains(errMsg, "separator") {
					return nil, fmt.Errorf("failed to read %q: error at line %d: invalid identity encoding: %s", path, lineNum, errMsg)
				}
				return nil, fmt.Errorf("failed to read %q: error at line %d: %s", path, lineNum, errMsg)
			}
			return nil, fmt.Errorf("failed to read %q: error at line %d: unknown identity type", path, lineNum)
		}
		// Unknown
		return nil, fmt.Errorf("failed to read %q: error at line %d: unknown identity type", path, lineNum)
	}

	return identities, nil
}

func decryptIdentityFileAsAge(encryptedContent []byte, path string) ([]byte, error) {
	// Parse header
	idx := bytes.Index(encryptedContent, []byte("\n--- "))
	if idx == -1 {
		return nil, fmt.Errorf("failed to read %q: failed to read header: EOF", path)
	}
	macEnd := bytes.Index(encryptedContent[idx+1:], []byte("\n"))
	if macEnd == -1 {
		return nil, fmt.Errorf("failed to read %q: failed to read header: EOF", path)
	}
	macEnd += idx + 1
	lines := bytes.Split(encryptedContent[:macEnd], []byte("\n"))
	var saltB64, wrappedB64 string
	var logN int
	for _, l := range lines {
		if bytes.HasPrefix(l, []byte("-> scrypt ")) {
			parts := bytes.Split(l, []byte(" "))
			if len(parts) >= 4 {
				saltB64 = string(parts[2])
				fmt.Sscanf(string(parts[3]), "%d", &logN)
			}
		} else if saltB64 != "" && wrappedB64 == "" && !bytes.HasPrefix(l, []byte("---")) && !bytes.HasPrefix(l, []byte("age-encryption")) {
