	}
	passphrase, err := readPassphrase(fmt.Sprintf("Enter passphrase for identity file %q: ", path), false)
	if err != nil {
		return nil, err
	}
	saltRaw, err := base64.RawStdEncoding.DecodeString(saltB64)
	if err != nil {
		return nil, err
	}
	scryptKey, err := scrypt.Key([]byte(passphrase), saltRaw, 1<<logN, 8, 1, 32)
	if err != nil {
		return nil, err
	}
	wrappedRaw, _ := base64.RawStdEncoding.DecodeString(wrappedB64)
	aead, _ := chacha20poly1305.New(scryptKey)
	fk, err := aead.Open(nil, make([]byte,12), wrappedRaw, nil)
	if err != nil {
