	}
	payloadCT := encryptedContent[macEnd+1:]
	prk := hkdfExtract(nil, fk)
	payloadKey := hkdfExpand(prk, []byte("payload"), 32)
	plaintext, err := decryptStream(payloadCT, payloadKey)
	if err != nil {
		return nil, err
	}
	return plaintext, nil
}

func encryptWithPassphrase(plaintext []byte, passphrase string) ([]byte, error) {
	// Generate salt 16 random
	salt := make([]byte, 16)
	rand.Read(salt)
	logN := 18
	scryptKey, err := scrypt.Key([]byte(passphrase), salt, 1<<logN, 8, 1, 32)
	if err != nil {
		return nil, err
	}
	fk := make([]byte, 16)
	rand.Read(fk)
	aead, _ := chacha20poly1305.New(scryptKey)
	wrapped := aead.Seal(nil, make([]byte,12), fk, nil)

	var header bytes.Buffer
	header.WriteString("age-encryption.org/v1\n")
	header.WriteString(fmt.Sprintf("-> scrypt %s %d\n", base64.RawStdEncoding.EncodeToString(salt), logN))
	header.WriteString(base64.RawStdEncoding.EncodeToString(wrapped) + "\n")
	headerNoMac := header.String() + "---"
	prk := hkdfExtract(nil, fk)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write([]byte(headerNoMac))
	macSum := mac.Sum(nil)
	header.WriteString("--- " + base64.RawStdEncoding.EncodeToString(macSum) + "\n")

	prkPayload := hkdfExtract(nil, fk)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	ct, err := encryptStream(plaintext, payloadKey)
	if err != nil {
		return nil, err
	}
	return append(header.Bytes(), ct...), nil
}

func decryptWithPassphrase(data []byte, passphrase string) ([]byte, error) {
	idx := bytes.Index(data, []byte("\n--- "))
	if idx == -1 {
		return nil, fmt.Errorf("failed to read header")
	}
	macEnd := bytes.Index(data[idx+1:], []byte("\n"))
	if macEnd == -1 {
		return nil, fmt.Errorf("failed to read header")
	}
	macEnd += idx + 1
	lines := bytes.Split(data[:macEnd], []byte("\n"))
	var saltB64, wrappedB64 string
	var logN int
	for _, l := range lines {
		if bytes.HasPrefix(l, []byte("-> scrypt ")) {
			parts := bytes.Split(l, []byte(" "))
			if len(parts) >= 4 {
				saltB64 = string(parts[2])
				fmt.Sscanf(string(parts[3]), "%d", &logN)
			}
		} else if saltB64 != "" && wrappedB64 == "" && !bytes.HasPrefix(l, []byte("---")) && !bytes.HasPrefix(l, []byte("age-encryption")) {
			wrappedB64 = string(l)
		}
	}
	if saltB64 == "" {
		return nil, fmt.Errorf("not scrypt")
	}
	salt, _ := base64.RawStdEncoding.DecodeString(saltB64)
	scryptKey, err := scrypt.Key([]byte(passphrase), salt, 1<<logN, 8, 1, 32)
	if err != nil {
		return nil, err
	}
	wrapped, _ := base64.RawStdEncoding.DecodeString(wrappedB64)
	aead, _ := chacha20poly1305.New(scryptKey)
	fk, err := aead.Open(nil, make([]byte,12), wrapped, nil)
	if err != nil {
		return nil, fmt.Errorf("incorrect passphrase")
	}
	// Verify header MAC
	hdr := data[:idx+4]
	prk := hkdfExtract(nil, fk)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write(hdr)
	calcMac := mac.Sum(nil)
	macLine := data[idx+1 : macEnd]
	macB64 := string(macLine[4:])
	expectedMac, _ := base64.RawStdEncoding.DecodeString(macB64)
	if !hmac.Equal(calcMac, expectedMac) {
		return nil, fmt.Errorf("bad header MAC")
	}
	payloadCT := data[macEnd+1:]
	prkPayload := hkdfExtract(nil, fk)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	return decryptStream(payloadCT, payloadKey)
}

func encryptToRecipients(plaintext []byte, recipients []interface{}) ([]byte, error) {
	fk := make([]byte, 16)
	rand.Read(fk)
	var stanzas []string
	for i, rec := range recipients {
		switch r := rec.(type) {
		case x25519Recipient:
			ephPriv := make([]byte, 32)
			rand.Read(ephPriv)
			ephPub, _ := curve25519.X25519(ephPriv, curve25519.Basepoint)
			shared, _ := curve25519.X25519(ephPriv, r.pub)
			salt := append(ephPub, r.pub...)
			prk := hkdfExtract(salt, shared)
			encKey := hkdfExpand(prk, []byte("age-encryption.org/v1/X25519"), 32)
			aead, _ := chacha20poly1305.New(encKey)
			wrapped := aead.Seal(nil, make([]byte,12), fk, nil)
			stanza := fmt.Sprintf("-> X25519 %s\n%s\n", base64.RawStdEncoding.EncodeToString(ephPub), base64.RawStdEncoding.EncodeToString(wrapped))
			stanzas = append(stanzas, stanza)
			_ = i
		case sshEd25519Recipient:
			ephPriv := make([]byte, 32)
			rand.Read(ephPriv)
			ephPub, _ := curve25519.X25519(ephPriv, curve25519.Basepoint)
			shared, _ := curve25519.X25519(ephPriv, r.xPub)
			salt := append(ephPub, r.xPub...)
			prk := hkdfExtract(salt, shared)
			encKey := hkdfExpand(prk, []byte("age-encryption.org/v1/X25519"), 32)
			aead, _ := chacha20poly1305.New(encKey)
			wrapped := aead.Seal(nil, make([]byte,12), fk, nil)
			stanza := fmt.Sprintf("-> ssh-ed25519 %s %s\n%s\n", r.tag, base64.RawStdEncoding.EncodeToString(ephPub), base64.RawStdEncoding.EncodeToString(wrapped))
			stanzas = append(stanzas, stanza)
		case sshRsaRecipient:
			label := []byte("age-encryption.org/v1/ssh-rsa")
			encrypted, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, r.pub, fk, label)
			if err != nil {
				return nil, err
			}
			b64Body := base64.RawStdEncoding.EncodeToString(encrypted)
			var body string
			for j := 0; j < len(b64Body); j += 64 {
				end := j + 64
				if end > len(b64Body) {
					end = len(b64Body)
				}
				body += b64Body[j:end] + "\n"
			}
			stanza := fmt.Sprintf("-> ssh-rsa %s\n%s", r.tag, body)
			stanzas = append(stanzas, stanza)
		case scryptRecipient:
			// This is from plugin batchpass
			salt := make([]byte, 16)
			rand.Read(salt)
			// Work factor from env? Default 18
			logN := 18
			if wfStr := os.Getenv("AGE_PASSPHRASE_WORK_FACTOR"); wfStr != "" {
				fmt.Sscanf(wfStr, "%d", &logN)
			}
			scryptKey, _ := scrypt.Key([]byte(r.passphrase), salt, 1<<logN, 8, 1, 32)
			aead, _ := chacha20poly1305.New(scryptKey)
			wrapped := aead.Seal(nil, make([]byte,12), fk, nil)
			stanza := fmt.Sprintf("-> scrypt %s %d\n%s\n", base64.RawStdEncoding.EncodeToString(salt), logN, base64.RawStdEncoding.EncodeToString(wrapped))
			stanzas = append(stanzas, stanza)
		default:
			return nil, fmt.Errorf("failed to wrap key for recipient #%d: %s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH", i, "yubikey", "yubikey", "age-plugin-yubikey")
		}
	}
	var header bytes.Buffer
	header.WriteString("age-encryption.org/v1\n")
	for _, s := range stanzas {
		header.WriteString(s)
	}
	headerNoMac := header.String() + "---"
	prk := hkdfExtract(nil, fk)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write([]byte(headerNoMac))
	macSum := mac.Sum(nil)
	header.WriteString("--- " + base64.RawStdEncoding.EncodeToString(macSum) + "\n")
	prkPayload := hkdfExtract(nil, fk)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	ct, err := encryptStream(plaintext, payloadKey)
	if err != nil {
		return nil, err
	}
	return append(header.Bytes(), ct...), nil
}

func encryptStream(plaintext, key []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	var out []byte
	counter := 0
	// Chunk plaintext into 64KiB
	for len(plaintext) > 0 {
		chunkSize := 64 * 1024
		if len(plaintext) < chunkSize {
			chunkSize = len(plaintext)
		}
		chunk := plaintext[:chunkSize]
		plaintext = plaintext[chunkSize:]
		// For all chunks except final empty, flag 0
		nonce := make([]byte, 12)
		binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
		// flag 0
		ct := aead.Seal(nil, nonce, chunk, nil)
		out = append(out, ct...)
		counter++
	}
	// Final empty chunk with flag 1
	nonce := make([]byte, 12)
	binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
	nonce[11] = 1
	ct := aead.Seal(nil, nonce, []byte{}, nil)
	out = append(out, ct...)
	return out, nil
}

func decryptStream(payloadCT, key []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	var out []byte
	counter := 0
	pos := 0
	for {
		remaining := len(payloadCT) - pos
		if remaining == 0 {
			break
		}
		// Determine chunk ciphertext length
		var chunkLen int
		if remaining > 64*1024+16 {
			chunkLen = 64*1024 + 16
		} else {
			// Last chunk(s): for small files, we have 2 chunks: first data+tag, second empty tag
			// Our encryption produces data chunks with flag0, final empty flag1
			// So for remaining, we need to try to find boundary: For remaining 43, first chunk 27, second 16
			// The first chunk length is not fixed, it could be up to 64K+16
			// For simplicity, if remaining == 16, it's final empty
			// If remaining > 16 and remaining <= 64K+16, it could be final data chunk with flag1? But our encryption always has final empty, so remaining should be data chunk + empty.
			// For files <64K, remaining is data chunk + empty. So we can split as remaining-16 and 16.

			// For generic decryption, we need to try to decrypt remaining as one chunk with flag1, and if that works and yields plaintext and pos+len == total, then it's last data chunk (when file size multiple of 64K? Actually then there is still final empty chunk, so not)

			// For simplicity, we will assume for remaining <= 64K+16, it's last data chunk with flag1 OR data chunk with flag0 + final empty?

			// Let's attempt: Try to decrypt remaining as final chunk with flag1, with whole remaining as ciphertext
			// If succeeds, it's last chunk (maybe empty or data)

			// Otherwise, try remaining-16 as data chunk flag0 and 16 as empty final

			// For our test file 43 bytes: first try remaining 43 as flag1 -> try decrypt 43 bytes with nonce counter0 flag1? Let's see

			// Actually for 11-byte file, our encryption produced: first chunk (11+16) flag0 counter0, second empty flag1 counter1
			// So remaining at start is 43. If we try to decrypt first 27 with flag0 counter0, it should succeed, leaving 16.

			// So we need to know chunk plaintext size to determine ciphertext size. Since plaintext size unknown, ciphertext size for data chunk is plaintext size +16, unknown.

			// Approach: Try to decrypt with increasing ciphertext sizes? For first chunk, plaintext size could be up to 64K, so ciphertext size up to 64K+16. For 43-byte payload, first chunk ciphertext could be 27 (11+16) + remaining 16 empty.

			// So we can try to find chunk boundary by trying to decrypt first 16..(remaining) bytes with flag0 counter0, and if succeeds, treat as chunk, continue.

			// For simplicity, we will attempt to decrypt with nonce flag0 and try ciphertext length = remaining -16 (assuming final empty) or remaining (if final data chunk)

			// Let's implement: For pos, try to decrypt payload[pos : pos+64K+16] as flag0, if succeeds, continue, else try as flag1

			// For small files, we will try first chunk as remaining-16 with flag0

			if remaining > 16 {
				// Try first chunk as remaining-16 with flag0
				candidateLen := remaining - 16
				nonce := make([]byte, 12)
				binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
				nonce[11] = 0
				pt, err := aead.Open(nil, nonce, payloadCT[pos:pos+candidateLen], nil)
				if err == nil {
					// Now try final empty chunk
					nonce1 := make([]byte, 12)
					binary.BigEndian.PutUint64(nonce1[3:11], uint64(counter+1))
					nonce1[11] = 1
					pt1, err1 := aead.Open(nil, nonce1, payloadCT[pos+candidateLen:], nil)
					if err1 == nil {
						out = append(out, pt...)
						out = append(out, pt1...)
						break
					}
					// If final empty fails, maybe first chunk is actually last data chunk with flag1 (no final empty)
					// Try first chunk as whole remaining with flag1
				}
			}
			// Try whole remaining as final chunk flag1
			nonce := make([]byte,12)
			binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
			nonce[11] = 1
			pt, err := aead.Open(nil, nonce, payloadCT[pos:], nil)
			if err == nil {
				out = append(out, pt...)
				break
			}
			// If not, try flag0 for whole remaining (maybe no final empty?)
			nonce[11] = 0
			pt, err = aead.Open(nil, nonce, payloadCT[pos:], nil)
			if err == nil {
				out = append(out, pt...)
				break
			}
			return nil, fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}

		nonce := make([]byte,12)
		binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
		nonce[11] = 0
		pt, err := aead.Open(nil, nonce, payloadCT[pos:pos+chunkLen], nil)
		if err != nil {
			return nil, fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
		out = append(out, pt...)
		pos += chunkLen
		counter++
	}
	return out, nil
}

