			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "flag needs an argument: %s\n", arg)
				fmt.Print(helpText)
				os.Exit(2)
			}
			outputPath = args[i+1]
			i++
		case "-r", "--recipient":
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "flag needs an argument: %s\n", arg)
				fmt.Print(helpText)
				os.Exit(2)
			}
			recipientStrs = append(recipientStrs, args[i+1])
			i++
		case "-R", "--recipients-file":
