				fmt.Fprintf(os.Stderr, "flag provided but not defined: %s\n", arg)
				fmt.Print(helpText)
				os.Exit(2)
			} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
				// check combined -e -d etc.
				isCombined := true
				for _, c := range arg[1:] {
					if c!='e' && c!='d' && c!='a' && c!='p' {
						isCombined = false
