func bech32Polymod(values []int) int {
	gen := []int{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	chk := 1
	for _, v := range values {
		b := chk >> 25
		chk = (chk & 0x1ffffff) << 5 ^ v
		for i := 0; i < 5; i++ {
			if ((b >> i) & 1) == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}

func bech32HrpExpand(hrp string) []int {
	var ret []int
	for _, c := range hrp {
		ret = append(ret, int(c>>5))
	}
	ret = append(ret, 0)
	for _, c := range hrp {
		ret = append(ret, int(c&31))
	}
	return ret
}

func bech32CreateChecksum(hrp string, data []int) []int {
	values := append(bech32HrpExpand(hrp), data...)
	pm := bech32Polymod(append(values, []int{0, 0, 0, 0, 0, 0}...)) ^ 1
	var ret []int
	for i := 0; i < 6; i++ {
		ret = append(ret, (pm>>5*(5-i))&31)
	}
	return ret
}

func bech32Decode(s string) (hrp string, data []int, errMsg string) {
	hasLower := false
	hasUpper := false
	for _, c := range s {
		if c >= 'a' && c <= 'z' {
			hasLower = true
		} else if c >= 'A' && c <= 'Z' {
			hasUpper = true
		}
	}
	if hasLower && hasUpper {
		return "", nil, "mixed case"
	}
	lower := strings.ToLower(s)
	pos := strings.LastIndex(lower, "1")
	if pos < 1 {
		return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	if len(lower)-pos-1 < 6 {
		return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	dataPart := lower[pos+1:]
	for i, c := range dataPart {
		if c == '1' {
			return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos+1+i, len(s))
		}
		if !strings.ContainsRune(charset, c) {
