func encryptToRecipients(plaintext []byte, recipients []interface{}) ([]byte, error) {
	fk := make([]byte, 16)
	rand.Read(fk)
	var stanzas []string
	for i, rec := range recipients {
		switch r := rec.(type) {
		case x25519Recipient:
			ephPriv := make([]byte, 32)
			rand.Read(ephPriv)
			ephPub, _ := curve25519.X25519(ephPriv, curve25519.Basepoint)
			shared, _ := curve25519.X25519(ephPriv, r.pub)
			salt := append(ephPub, r.pub...)
			prk := hkdfExtract(salt, shared)
			encKey := hkdfExpand(prk, []byte("age-encryption.org/v1/X25519"), 32)
			aead, _ := chacha20poly1305.New(encKey)
			wrapped := aead.Seal(nil, make([]byte,12), fk, nil)
			stanza := fmt.Sprintf("-> X25519 %s\n%s\n", base64.RawStdEncoding.EncodeToString(ephPub), base64.RawStdEncoding.EncodeToString(wrapped))
			stanzas = append(stanzas, stanza)
			_ = i
		default:
			return nil, fmt.Errorf("unsupported recipient type")
		}
	}
	var header bytes.Buffer
	header.WriteString("age-encryption.org/v1\n")
	for _, s := range stanzas {
		header.WriteString(s)
	}
	headerNoMac := header.String() + "---"
	prk := hkdfExtract(nil, fk)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write([]byte(headerNoMac))
	macSum := mac.Sum(nil)
	header.WriteString("--- " + base64.RawStdEncoding.EncodeToString(macSum) + "\n")
	prkPayload := hkdfExtract(nil, fk)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	ct, err := encryptStream(plaintext, payloadKey)
	if err != nil {
		return nil, err
	}
	return append(header.Bytes(), ct...), nil
}

func encryptStream(plaintext, key []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	var out []byte
	counter := 0
	// Encrypt in 64KiB chunks with flag 0, then final empty flag1
	for len(plaintext) > 0 {
		chunkSize := 64 * 1024
		if len(plaintext) < chunkSize {
			chunkSize = len(plaintext)
		}
		chunk := plaintext[:chunkSize]
		plaintext = plaintext[chunkSize:]
		nonce := make([]byte, 12)
		binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
		ct := aead.Seal(nil, nonce, chunk, nil)
		out = append(out, ct...)
		counter++
	}
	nonce := make([]byte, 12)
	binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
	nonce[11] = 1
	ct := aead.Seal(nil, nonce, []byte{}, nil)
	out = append(out, ct...)
	return out, nil
}

func decryptStream(payloadCT, key []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	var out []byte
	counter := 0
	pos := 0
	for {
		remaining := len(payloadCT) - pos
		if remaining == 0 {
			break
		}
		var chunkLen int
		if remaining > 64*1024+16 {
			chunkLen = 64*1024 + 16
		} else {
			// For last chunks, try to split as we did in encryption: remaining is either data chunk + empty, or just empty, or data chunk alone (if file size exactly multiple? but we always have final empty, so remaining should be data+empty or empty)
			// For simplicity, if remaining == 16, it's final empty
			// If remaining >16, first try remaining-16 as data chunk flag0 and 16 as empty flag1
			// If that fails, try remaining as final data chunk flag1
			if remaining > 16 {
				candidateLen := remaining - 16
				// Try decrypt candidateLen as flag0
				nonce0 := make([]byte,12)
				binary.BigEndian.PutUint64(nonce0[3:11], uint64(counter))
				nonce0[11]=0
				pt0, err0 := aead.Open(nil, nonce0, payloadCT[pos:pos+candidateLen], nil)
				if err0==nil{
					// Try final empty
					nonce1 := make([]byte,12)
					binary.BigEndian.PutUint64(nonce1[3:11], uint64(counter+1))
					nonce1[11]=1
					pt1, err1 := aead.Open(nil, nonce1, payloadCT[pos+candidateLen:], nil)
					if err1==nil{
						out = append(out, pt0...)
						out = append(out, pt1...)
						break
					}
				}
			}
			// Try whole remaining as final chunk flag1
			nonce := make([]byte,12)
			binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
			nonce[11]=1
			pt, err := aead.Open(nil, nonce, payloadCT[pos:], nil)
			if err==nil{
				out = append(out, pt...)
				break
			}
			// Try flag0 for whole remaining (maybe no final empty? For empty file, we have 2 chunks, so this case shouldn't happen)
			nonce[11]=0
			pt, err = aead.Open(nil, nonce, payloadCT[pos:], nil)
			if err==nil{
				out = append(out, pt...)
				break
			}
			return nil, fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
		nonce := make([]byte,12)
		binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
		pt, err := aead.Open(nil, nonce, payloadCT[pos:pos+chunkLen], nil)
		if err != nil {
			return nil, fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
		out = append(out, pt...)
		pos+=chunkLen
		counter++
	}
	return out, nil
}

func decryptWithIdentities(data []byte, identities [][]byte) ([]byte, error) {
	idx := bytes.Index(data, []byte("\n--- "))
	if idx == -1 {
		return nil, fmt.Errorf("failed to read header: parsing age header: failed to read header: EOF")
	}
	macEnd := bytes.Index(data[idx+1:], []byte("\n"))
	if macEnd == -1 {
		return nil, fmt.Errorf("failed to read header: parsing age header: failed to read header: EOF")
	}
	macEnd += idx + 1
	lines := bytes.Split(data[:macEnd], []byte("\n"))
	type stanza struct {
		typ string
		args []string
		body []byte
	}
	var stanzas []stanza
	var current *stanza
	for _, l := range lines {
		if bytes.HasPrefix(l, []byte("-> ")) {
			if current != nil {
				stanzas = append(stanzas, *current)
			}
			parts := strings.Fields(string(l))
			if len(parts) < 2 {
				continue
			}
			current = &stanza{typ: parts[1], args: parts[2:]}
		} else if current != nil {
			b, err := base64.RawStdEncoding.DecodeString(string(l))
			if err != nil {
				b, _ = base64.StdEncoding.DecodeString(string(l))
			}
			current.body = append(current.body, b...)
		}
	}
	if current != nil {
		stanzas = append(stanzas, *current)
	}

	var fileKey []byte
	for _, s := range stanzas {
		if s.typ == "X25519" {
			if len(s.args) < 1 {
				continue
			}
			ephPub, err := base64.RawStdEncoding.DecodeString(s.args[0])
			if err != nil {
				continue
			}
			for _, priv := range identities {
				shared, err := curve25519.X25519(priv, ephPub)
				if err != nil {
					continue
				}
				recPub, _ := curve25519.X25519(priv, curve25519.Basepoint)
				salt := append(ephPub, recPub...)
				prk := hkdfExtract(salt, shared)
				encKey := hkdfExpand(prk, []byte("age-encryption.org/v1/X25519"), 32)
				aead, _ := chacha20poly1305.New(encKey)
				fk, err := aead.Open(nil, make([]byte,12), s.body, nil)
				if err == nil {
					fileKey = fk
					break
				}
			}
		}
		if fileKey != nil {
			break
		}
	}
	if fileKey == nil {
		return nil, fmt.Errorf("no identity matched any of the recipients")
	}
	// Verify MAC
	hdr := data[:idx+4]
	prk := hkdfExtract(nil, fileKey)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write(hdr)
	calcMac := mac.Sum(nil)
	macLine := data[idx+1 : macEnd]
	macB64 := string(macLine[4:])
	expectedMac, _ := base64.RawStdEncoding.DecodeString(macB64)
	if !hmac.Equal(calcMac, expectedMac) {
		return nil, fmt.Errorf("bad header MAC")
	}
	payloadCT := data[macEnd+1:]
	prkPayload := hkdfExtract(nil, fileKey)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	return decryptStream(payloadCT, payloadKey)
}

