	)
	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-e", "--encrypt":
			encryptExplicit = true
		case "-d", "--decrypt":
			decryptFlag = true
		case "-a", "--armor":
			armorFlag = true
		case "-p", "--passphrase":
			passphraseFlag = true
