			fmt.Fprintf(os.Stderr, "Enter passphrase: ")
			// For decrypt, read passphrase without confirmation
			// Use readPassphrase with confirm false but prompt already printed, so we need to read without prompt duplication

			// Actually readPassphrase prints its own prompt, so we shouldn't print above. Let's just call readPassphrase with same prompt but we already printed?

			// We'll use readPassphrase that prints prompt itself

			// Remove above print and use below

			// For simplicity, we will call readPassphrase with prompt "Enter passphrase: "

			// But we already printed, so we will not print again, just read from tty directly

			tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
