	for _, v := range data {
		acc = (acc << 5) | v
		bits += 5
		for bits >= 8 {
			bits -= 8
			ret = append(ret, byte((acc>>bits)&0xff))
		}
	}
	return ret, nil
}
func convertBits8to5(data []byte) []int {
	acc := 0
	bits := 0
