			if _, err := os.Stat(dir); err != nil {
				fmt.Fprintf(os.Stderr, "age: error: failed to write header: open %s: no such file or directory\n", outputPath)
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
		}
	}
