func convertBits5to8(data []int) ([]byte, error) {
	acc := 0
	bits := 0
	var ret []byte
	for _, v := range data {
		acc = (acc << 5) | v
		bits += 5
		for bits >= 8 {
			bits -= 8
			ret = append(ret, byte((acc>>bits)&0xff))
		}
	}
	return ret, nil
}
func convertBits8to5(data []byte) []int {
	acc := 0
	bits := 0
	var ret []int
	maxv := 31
	for _, b := range data {
		acc = (acc << 8) | int(b)
		bits += 8
		for bits >= 5 {
			bits -= 5
			ret = append(ret, (acc>>bits)&maxv)
		}
	}
	if bits > 0 {
		ret = append(ret, (acc<<(5-bits))&maxv)
	}
	return ret
}
func hkdfExtract(salt, ikm []byte) []byte {
	if salt == nil {
