		fmt.Fprint(os.Stderr, helpText)
		os.Exit(1)
	}
	var (
		decryptFlag     bool
		armorFlag       bool
		passphraseFlag  bool
		outputPath      string
		recipientStrs   []string
		recipientsFiles []string
		identityPaths   []string
		inputPath       string
