					pt1, err1 := aead.Open(nil, nonce1, payloadCT[pos+candidateLen:], nil)
					if err1 == nil {
						out = append(out, pt0...)
						out = append(out, pt1...)
						break
					}
				}
			}
			nonce := make([]byte, 12)
			binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
			nonce[11] = 1
			pt, err := aead.Open(nil, nonce, payloadCT[pos:], nil)
			if err == nil {
				out = append(out, pt...)
				break
			}
			nonce[11] = 0
			pt, err = aead.Open(nil, nonce, payloadCT[pos:], nil)
			if err == nil {
				out = append(out, pt...)
				break
			}
			return nil, fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
		nonce := make([]byte, 12)
		binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
		pt, err := aead.Open(nil, nonce, payloadCT[pos:pos+chunkLen], nil)
		if err != nil {
			return nil, fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
		out = append(out, pt...)
		pos += chunkLen
		counter++
	}
	return out, nil
}
func decryptWithIdentities(data []byte, identities [][]byte) ([]byte, error) {
	idx := bytes.Index(data, []byte("\n--- "))
	if idx == -1 {
		return nil, fmt.Errorf("failed to read header: parsing age header: failed to read header: EOF")
	}
	macEnd := bytes.Index(data[idx+1:], []byte("\n"))
	if macEnd == -1 {
		return nil, fmt.Errorf("failed to read header: parsing age header: failed to read header: EOF")
	}
	macEnd += idx + 1
	headerPart := data[:macEnd]
	lines := bytes.Split(headerPart, []byte("\n"))
	type stanza struct {
		typ  string
		args []string
		body []byte
	}
	var stanzas []stanza
	var cur *stanza
	for _, l := range lines {
		if bytes.HasPrefix(l, []byte("-> ")) {
			if cur != nil {
				stanzas = append(stanzas, *cur)
			}
			parts := strings.Fields(string(l))
			if len(parts) < 2 {
				continue
			}
			cur = &stanza{typ: parts[1], args: parts[2:]}
		} else if cur != nil {
			b, err := base64.RawStdEncoding.DecodeString(string(l))
			if err != nil {
				b, _ = base64.StdEncoding.DecodeString(string(l))
			}
			cur.body = append(cur.body, b...)
		}
	}
	if cur != nil {
		stanzas = append(stanzas, *cur)
	}
	var fileKey []byte
	for _, s := range stanzas {
		if s.typ == "X25519" {
			if len(s.args) < 1 {
				continue
			}
			ephPub, err := base64.RawStdEncoding.DecodeString(s.args[0])
			if err != nil {
				continue
			}
			for _, priv := range identities {
				shared, err := curve25519.X25519(priv, ephPub)
				if err != nil {
					continue
				}
				recPub, _ := curve25519.X25519(priv, curve25519.Basepoint)
				salt := append(ephPub, recPub...)
				prk := hkdfExtract(salt, shared)
				encKey := hkdfExpand(prk, []byte("age-encryption.org/v1/X25519"), 32)
				aead, _ := chacha20poly1305.New(encKey)
				fk, err := aead.Open(nil, make([]byte,12), s.body, nil)
				if err == nil {
					fileKey = fk
					break
				}
			}
		}
		if fileKey != nil {
			break
		}
	}
	if fileKey == nil {
		return nil, fmt.Errorf("no identity matched any of the recipients")
	}
	hdr := data[:idx+4]
	prk := hkdfExtract(nil, fileKey)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write(hdr)
	calcMac := mac.Sum(nil)
	macLine := data[idx+1 : macEnd]
	macB64 := string(macLine[4:])
	expectedMac, _ := base64.RawStdEncoding.DecodeString(macB64)
	if !hmac.Equal(calcMac, expectedMac) {
		return nil, fmt.Errorf("bad header MAC")
	}
	payloadCT := data[macEnd+1:]
	prkPayload := hkdfExtract(nil, fileKey)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	return decryptStream(payloadCT, payloadKey)
}
func encryptFileToRecipients(plaintext []byte, recipients []interface{}) ([]byte, error) {
	fk := make([]byte, 16)
	rand.Read(fk)
	var stanzas []string
	for _, rec := range recipients {
		switch r := rec.(type) {
		case x25519Recipient:
			ephPriv := make([]byte, 32)
			rand.Read(ephPriv)
			ephPub, _ := curve25519.X25519(ephPriv, curve25519.Basepoint)
			shared, _ := curve25519.X25519(ephPriv, r.pub)
			salt := append(ephPub, r.pub...)
			prk := hkdfExtract(salt, shared)
			encKey := hkdfExpand(prk, []byte("age-encryption.org/v1/X25519"), 32)
			aead, _ := chacha20poly1305.New(encKey)
			wrapped := aead.Seal(nil, make([]byte,12), fk, nil)
			stanza := fmt.Sprintf("-> X25519 %s\n%s\n", base64.RawStdEncoding.EncodeToString(ephPub), base64.RawStdEncoding.EncodeToString(wrapped))
			stanzas = append(stanzas, stanza)
		default:
			return nil, fmt.Errorf("unsupported recipient")
		}
	}
	var header bytes.Buffer
	header.WriteString("age-encryption.org/v1\n")
	for _, s := range stanzas {
		header.WriteString(s)
	}
	headerNoMac := header.String() + "---"
	prk := hkdfExtract(nil, fk)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write([]byte(headerNoMac))
	macSum := mac.Sum(nil)
	header.WriteString("--- " + base64.RawStdEncoding.EncodeToString(macSum) + "\n")
	prkPayload := hkdfExtract(nil, fk)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	ct, err := encryptStream(plaintext, payloadKey)
	if err != nil {
		return nil, err
	}
	return append(header.Bytes(), ct...), nil
}
func main() {
	for _, arg := range os.Args[1:] {
		if arg == "--version" {
			fmt.Println(version)
			os.Exit(0)
		}
		if arg == "--help" || arg == "-h" {
			fmt.Fprint(os.Stderr, helpText)
			os.Exit(0)
		}
	}
	if len(os.Args) == 1 {
		fmt.Fprint(os.Stderr, helpText)
		os.Exit(1)
	}
	var (
		decryptFlag     bool
		armorFlag       bool
		passphraseFlag  bool
		outputPath      string
		recipientStrs   []string
		recipientsFiles []string
		identityPaths   []string
		inputPath       string
		encryptExplicit bool
	)
	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-e", "--encrypt":
			encryptExplicit = true
		case "-d", "--decrypt":
			decryptFlag = true
		case "-a", "--armor":
			armorFlag = true
		case "-p", "--passphrase":
			passphraseFlag = true
		case "-o", "--output":
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "flag needs an argument: %s\n", arg)
				fmt.Fprint(os.Stderr, helpText)
				os.Exit(2)
			}
			outputPath = args[i+1]
			i++
		case "-r", "--recipient":
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "flag needs an argument: %s\n", arg)
				fmt.Fprint(os.Stderr, helpText)
				os.Exit(2)
			}
			recipientStrs = append(recipientStrs, args[i+1])
			i++
		case "-R", "--recipients-file":
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "flag needs an argument: %s\n", arg)
				fmt.Fprint(os.Stderr, helpText)
				os.Exit(2)
			}
			recipientsFiles = append(recipientsFiles, args[i+1])
			i++
		case "-i", "--identity":
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "flag needs an argument: %s\n", arg)
				fmt.Fprint(os.Stderr, helpText)
				os.Exit(2)
			}
			identityPaths = append(identityPaths, args[i+1])
			i++
		case "-j":
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "flag needs an argument: -j\n")
				fmt.Fprint(os.Stderr, helpText)
				os.Exit(2)
			}
			pluginName := args[i+1]
			i++
			fmt.Fprintf(os.Stderr, "age: error: failed to wrap key for recipient #0: %s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH\n", pluginName, pluginName, "age-plugin-"+pluginName)
			fmt.Fprintf(os.Stderr, "age: hint: you might want to install the %q plugin\n", pluginName)
			fmt.Fprintf(os.Stderr, "age: hint: visit https://age-encryption.org/awesome#plugins for a list of available plugins\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		default:
			if strings.HasPrefix(arg, "--output=") {
				outputPath = strings.TrimPrefix(arg, "--output=")
			} else if strings.HasPrefix(arg, "-o") && len(arg) > 2 {
				outputPath = arg[2:]
			} else if strings.HasPrefix(arg, "--recipient=") {
				recipientStrs = append(recipientStrs, strings.TrimPrefix(arg, "--recipient="))
			} else if strings.HasPrefix(arg, "-r") && len(arg) > 2 {
				recipientStrs = append(recipientStrs, arg[2:])
			} else if strings.HasPrefix(arg, "--recipients-file=") {
				recipientsFiles = append(recipientsFiles, strings.TrimPrefix(arg, "--recipients-file="))
			} else if strings.HasPrefix(arg, "--identity=") {
				identityPaths = append(identityPaths, strings.TrimPrefix(arg, "--identity="))
			} else if strings.HasPrefix(arg, "--") {
				flagName := strings.TrimLeft(arg, "-")
				fmt.Fprintf(os.Stderr, "flag provided but not defined: -%s\n", flagName)
				fmt.Fprint(os.Stderr, helpText)
				os.Exit(2)
			} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
				isCombined := true
				for _, c := range arg[1:] {
					if c != 'e' && c != 'd' && c != 'a' && c != 'p' {
						isCombined = false
						break
					}
				}
				if isCombined {
					for _, c := range arg[1:] {
						switch c {
						case 'e':
							encryptExplicit = true
						case 'd':
							decryptFlag = true
						case 'a':
							armorFlag = true
						case 'p':
							passphraseFlag = true
						}
					}
				} else {
					fmt.Fprintf(os.Stderr, "flag provided but not defined: %s\n", arg)
					fmt.Fprint(os.Stderr, helpText)
					os.Exit(2)
				}
			} else {
				if inputPath != "" {
					fmt.Fprintf(os.Stderr, "age: error: too many INPUT arguments: %q %q\n", inputPath, arg)
					fmt.Fprintf(os.Stderr, "age: hint: only a single input file may be specified at a time\n")
					fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
					os.Exit(1)
				}
				inputPath = arg
			}
		}
	}
	if decryptFlag && passphraseFlag {
		fmt.Fprintf(os.Stderr, "age: error: -p/--passphrase can't be used with -d/--decrypt\n")
		fmt.Fprintf(os.Stderr, "age: hint: note that password protected files are detected automatically\n")
		fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
		os.Exit(1)
	}
	if decryptFlag {
		if len(recipientStrs) > 0 {
			fmt.Fprintf(os.Stderr, "age: error: -r/--recipient can't be used with -d/--decrypt\n")
			fmt.Fprintf(os.Stderr, "age: hint: did you mean to use -i/--identity to specify a private key?\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		if len(recipientsFiles) > 0 {
			fmt.Fprintf(os.Stderr, "age: error: -R/--recipients-file can't be used with -d/--decrypt\n")
			fmt.Fprintf(os.Stderr, "age: hint: did you mean to use -i/--identity to specify a private key?\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
	}
	if len(identityPaths) > 0 && !decryptFlag && !encryptExplicit {
		fmt.Fprintf(os.Stderr, "age: error: -i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt\n")
		fmt.Fprintf(os.Stderr, "age: hint: did you forget to specify -d/--decrypt?\n")
		fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
		os.Exit(1)
	}
	if passphraseFlag {
		if len(recipientStrs) > 0 {
			fmt.Fprintf(os.Stderr, "age: error: -p/--passphrase can't be combined with -r/--recipient\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		if len(recipientsFiles) > 0 {
			fmt.Fprintf(os.Stderr, "age: error: -p/--passphrase can't be combined with -R/--recipients-file\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		if len(identityPaths) > 0 && encryptExplicit {
			fmt.Fprintf(os.Stderr, "age: error: -p/--passphrase can't be combined with -i/--identity and -j\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
	}
	if !decryptFlag && !passphraseFlag && len(recipientStrs) == 0 && len(recipientsFiles) == 0 && len(identityPaths) == 0 {
		fmt.Fprintf(os.Stderr, "age: error: missing recipients\n")
		fmt.Fprintf(os.Stderr, "age: hint: did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?\n")
		fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
		os.Exit(1)
	}
	for _, rf := range recipientsFiles {
		if rf == "-" && inputPath == "" {
			fmt.Fprintf(os.Stderr, "age: error: failed to parse recipient file \"-\": standard input is used for multiple purposes\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
	}
	for _, idp := range identityPaths {
		if idp == "-" && inputPath == "" {
			fmt.Fprintf(os.Stderr, "age: error: reading \"-\": standard input is used for multiple purposes\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
	}
	if inputPath != "" && inputPath != "-" {
		if _, err := os.Stat(inputPath); err != nil {
			fmt.Fprintf(os.Stderr, "age: error: failed to open input file %q: open %s: no such file or directory\n", inputPath, inputPath)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
	}
	if outputPath != "" && outputPath != "-" {
		dir := filepath.Dir(outputPath)
		if dir != "" && dir != "." {
			if _, err := os.Stat(dir); err != nil {
				fmt.Fprintf(os.Stderr, "age: error: failed to write header: open %s: no such file or directory\n", outputPath)
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
		}
	}
	if !decryptFlag {
		if outputPath == "" {
			if term.IsTerminal(int(os.Stdout.Fd())) && !armorFlag {
				fmt.Fprintf(os.Stderr, "age: error: refusing to output binary to the terminal\n")
				fmt.Fprintf(os.Stderr, "age: hint: did you mean to use -a/--armor?\n")
				fmt.Fprintf(os.Stderr, "age: hint: force anyway with \"-o -\"\n")
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
		}
	}
	var recipients []interface{}
	for _, recStr := range recipientStrs {
		rec, err := parseRecipient(recStr)
		if err != nil {
			if strings.Contains(err.Error(), "plugin") {
				fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
				lower := strings.ToLower(recStr)
				pluginName := "unknown"
				if idx := strings.Index(lower, "1"); idx != -1 {
					if idx2 := strings.Index(lower[idx+1:], "1"); idx2 != -1 {
						pluginName = lower[idx+1 : idx+1+idx2]
					}
				}
				fmt.Fprintf(os.Stderr, "age: hint: you might want to install the %q plugin\n", pluginName)
				fmt.Fprintf(os.Stderr, "age: hint: visit https://age-encryption.org/awesome#plugins for a list of available plugins\n")
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		recipients = append(recipients, rec)
	}
	for _, rf := range recipientsFiles {
		recs, err := readRecipientsFile(rf)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		recipients = append(recipients, recs...)
	}
	var inputData []byte
	var err error
	if inputPath == "" || inputPath == "-" {
		inputData, err = io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			os.Exit(1)
		}
	} else {
		inputData, err = os.ReadFile(inputPath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: failed to open input file %q: open %s: no such file or directory\n", inputPath, inputPath)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
	}
	if decryptFlag {
		isArmor := bytes.Contains(inputData, []byte("BEGIN AGE ENCRYPTED FILE"))
		var rawData []byte
		if isArmor {
			rawData, err = decodeArmor(inputData)
			if err != nil {
				fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
				os.Exit(1)
			}
		} else {
			rawData = inputData
		}
		if len(identityPaths) == 0 {
			fmt.Fprintf(os.Stderr, "age: error: the file is not passphrase-encrypted, identities are required\n")
			fmt.Fprintf(os.Stderr, "age: hint: specify identities with -i/--identity or -j to decrypt this file\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		var idGroups [][]byte
		for _, idPath := range identityPaths {
			ids, err := parseIdentityFile(idPath)
			if err != nil {
				fmt.Fprintf(os.Stderr, "age: error: reading %q: %v\n", idPath, err)
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
			idGroups = append(idGroups, ids...)
		}
		plain, err := decryptWithIdentities(rawData, idGroups)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		if outputPath == "" || outputPath == "-" {
			os.Stdout.Write(plain)
		} else {
			os.WriteFile(outputPath, plain, 0644)
		}
		os.Exit(0)
	} else {
		if passphraseFlag {
			fmt.Fprintf(os.Stderr, "age: error: -p/--passphrase not implemented in this minimal build\n")
			os.Exit(1)
		}
		enc, err := encryptFileToRecipients(inputData, recipients)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		var outData []byte
		if armorFlag {
			outData = encodeArmor(enc)
		} else {
			outData = enc
		}
		if outputPath == "" || outputPath == "-" {
			os.Stdout.Write(outData)
		} else {
			os.WriteFile(outputPath, outData, 0644)
		}
		os.Exit(0)
	}
}
GO
"}

