	var ret []int
	for i := 0; i < 6; i++ {
		ret = append(ret, (pm>>5*(5-i))&31)
	}
	return ret
}
func bech32Decode(s string) (hrp string, data []int, errMsg string) {
	hasLower := false
	hasUpper := false
	for _, c := range s {
		if c >= 'a' && c <= 'z' {
			hasLower = true
		} else if c >= 'A' && c <= 'Z' {
			hasUpper = true
		}
	}
	if hasLower && hasUpper {
		return "", nil, "mixed case"
	}
	lower := strings.ToLower(s)
	pos := strings.LastIndex(lower, "1")
	if pos < 1 {
		return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	if len(lower)-pos-1 < 6 {
		return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	dataPart := lower[pos+1:]
	for i, c := range dataPart {
		if c == '1' {
			return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos+1+i, len(s))
		}
		if !strings.ContainsRune(charset, c) {
			return "", nil, fmt.Sprintf("invalid character data part: s[%d]=%d", i, c)
		}
	}
