func bech32Polymod(values []int) int {
	gen := []int{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	chk := 1
	for _, v := range values {
		b := chk >> 25
		chk = (chk & 0x1ffffff) << 5 ^ v
		for i := 0; i < 5; i++ {
			if ((b >> i) & 1) == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}
func bech32HrpExpand(hrp string) []int {
	var ret []int
	for _, c := range hrp {
		ret = append(ret, int(c>>5))
	}
	ret = append(ret, 0)
	for _, c := range hrp {
		ret = append(ret, int(c&31))
	}
	return ret
}
func bech32CreateChecksum(hrp string, data []int) []int {
	values := append(bech32HrpExpand(hrp), data...)
	pm := bech32Polymod(append(values, []int{0, 0, 0, 0, 0, 0}...)) ^ 1
	var ret []int
	for i := 0; i < 6; i++ {
		ret = append(ret, (pm>>5*(5-i))&31)
	}
	return ret
}
func bech32Decode(s string) (hrp string, data []int, errMsg string) {
	hasLower := false
	hasUpper := false
	for _, c := range s {
		if c >= 'a' && c <= 'z' {
			hasLower = true
		} else if c >= 'A' && c <= 'Z' {
			hasUpper = true
		}
	}
	if hasLower && hasUpper {
		return "", nil, "mixed case"
	}
	lower := strings.ToLower(s)
	pos := strings.LastIndex(lower, "1")
	if pos < 1 {
		return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	if len(lower)-pos-1 < 6 {
		return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	dataPart := lower[pos+1:]
	for i, c := range dataPart {
		if c == '1' {
			return "", nil, fmt.Sprintf("separator '1' at invalid position: pos=%d, len=%d", pos+1+i, len(s))
		}
		if !strings.ContainsRune(charset, c) {
			return "", nil, fmt.Sprintf("invalid character data part: s[%d]=%d", i, c)
		}
	}
	var vals []int
	for _, c := range dataPart {
		vals = append(vals, strings.IndexRune(charset, c))
	}
	if bech32Polymod(append(bech32HrpExpand(lower[:pos]), vals...)) != 1 {
		return "", nil, "invalid checksum"
	}
	hrp = lower[:pos]
	data = vals[:len(vals)-6]
	return hrp, data, ""
}
func convertBits5to8(data []int) ([]byte, error) {
	acc := 0
	bits := 0
	var ret []byte
	for _, v := range data {
		acc = (acc << 5) | v
		bits += 5
		for bits >= 8 {
			bits -= 8
			ret = append(ret, byte((acc>>bits)&0xff))
		}
	}
	return ret, nil
}
func convertBits8to5(data []byte) []int {
	acc := 0
	bits := 0
	var ret []int
	maxv := 31
	for _, b := range data {
		acc = (acc << 8) | int(b)
		bits += 8
		for bits >= 5 {
			bits -= 5
			ret = append(ret, (acc>>bits)&maxv)
		}
	}
	if bits > 0 {
		ret = append(ret, (acc<<(5-bits))&maxv)
	}
	return ret
}
func hkdfExtract(salt, ikm []byte) []byte {
	if salt == nil {
		salt = make([]byte, 32)
	}
	mac := hmac.New(sha256.New, salt)
	mac.Write(ikm)
	return mac.Sum(nil)
}
func hkdfExpand(prk, info []byte, length int) []byte {
	r := hkdf.Expand(sha256.New, prk, info)
	out := make([]byte, length)
	io.ReadFull(r, out)
	return out
}
type x25519Recipient struct {
	pub []byte
	raw string
}
func parseRecipient(rec string) (interface{}, error) {
	lower := strings.ToLower(rec)
	if strings.HasPrefix(lower, "age1") {
		hrp, data5, errMsg := bech32Decode(rec)
		if errMsg != "" {
			countOnes := strings.Count(lower, "1")
			if strings.Contains(errMsg, "separator '1' at invalid position") {
				if countOnes == 1 {
					return nil, fmt.Errorf("malformed recipient %q: %s", rec, errMsg)
				} else {
					if strings.HasPrefix(lower, "age1tag1") || strings.HasPrefix(lower, "age1tagpq1") {
						return nil, fmt.Errorf("malformed recipient %q: invalid recipient encoding: %s", rec, errMsg)
					}
					return nil, fmt.Errorf("invalid recipient encoding: %s", errMsg)
				}
			}
			if countOnes > 1 {
				if strings.HasPrefix(lower, "age1tag1") || strings.HasPrefix(lower, "age1tagpq1") {
					return nil, fmt.Errorf("malformed recipient %q: invalid recipient encoding: %s", rec, errMsg)
				}
				return nil, fmt.Errorf("invalid recipient encoding: %s", errMsg)
			}
			return nil, fmt.Errorf("malformed recipient %q: %s", rec, errMsg)
		}
		data8, _ := convertBits5to8(data5)
		switch hrp {
		case "age":
			if len(data8) != 32 {
				return nil, fmt.Errorf("malformed recipient %q: invalid length", rec)
			}
			return x25519Recipient{pub: data8, raw: rec}, nil
		case "age1tag":
			if len(data8) == 32 {
				return nil, fmt.Errorf("malformed recipient %q: invalid tag recipient public key size %d", rec, len(data8))
			}
			return nil, fmt.Errorf("malformed recipient %q: invalid tag recipient public key size %d", rec, len(data8))
		default:
			if strings.HasPrefix(hrp, "age1") {
				pluginName := hrp[4:]
				return nil, fmt.Errorf("failed to wrap key for recipient #0: %s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH", pluginName, pluginName, "age-plugin-"+pluginName)
			}
			return nil, fmt.Errorf("unknown recipient type: %q", rec)
		}
	}
	if strings.HasPrefix(rec, "ssh-") {
		return nil, fmt.Errorf("unknown recipient type: %q", rec)
	}
	return nil, fmt.Errorf("unknown recipient type: %q", rec)
}
func readRecipientsFile(path string) ([]interface{}, error) {
	var data []byte
	var err error
	if path == "-" {
		data, err = io.ReadAll(os.Stdin)
		if err != nil {
			return nil, err
		}
	} else {
		data, err = os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("failed to open file: %v", err)
		}
	}
	var recipients []interface{}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		rec, err := parseRecipient(line)
		if err != nil {
			if strings.Contains(err.Error(), "unknown recipient type") || strings.Contains(err.Error(), "malformed recipient") {
				return nil, fmt.Errorf("failed to parse recipient file %q: %q: malformed recipient at line %d", path, path, lineNum)
			}
			return nil, fmt.Errorf("failed to parse recipient file %q: %q: %v", path, path, err)
		}
		recipients = append(recipients, rec)
	}
	if len(recipients) == 0 {
		return nil, fmt.Errorf("failed to parse recipient file %q: %q: no recipients found", path, path)
	}
	return recipients, nil
}
func parseIdentityFile(path string) ([][]byte, error) {
	var content []byte
	var err error
	if path == "-" {
		content, err = io.ReadAll(os.Stdin)
		if err != nil {
			return nil, err
		}
	} else {
		content, err = os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("failed to open file: %v", err)
		}
	}
	trimmed := bytes.TrimSpace(content)
	if bytes.Contains(trimmed, []byte("BEGIN AGE ENCRYPTED FILE")) {
		decoded, err := decodeArmor(trimmed)
		if err != nil {
			return nil, err
		}
		trimmed = decoded
	}
	if bytes.HasPrefix(trimmed, []byte("age-encryption.org/v1")) && bytes.Contains(trimmed, []byte("-> scrypt ")) {
		pass, err := readPassphrase(fmt.Sprintf("Enter passphrase for identity file %q: ", path), false)
		if err != nil {
			return nil, err
		}
		plain, err := decryptFileWithPassphrase(trimmed, pass)
		if err != nil {
			return nil, err
		}
		content = plain
	} else {
		content = trimmed
	}
	var identities [][]byte
	scanner := bufio.NewScanner(bytes.NewReader(content))
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "AGE-SECRET-KEY-1") {
			hrp, data5, errMsg := bech32Decode(line)
			if errMsg != "" {
				return nil, fmt.Errorf("failed to read %q: error at line %d: malformed secret key: %s", path, lineNum, errMsg)
			}
			if hrp != "age-secret-key-" {
				return nil, fmt.Errorf("failed to read %q: error at line %d: unknown identity type", path, lineNum)
			}
			data8, _ := convertBits5to8(data5)
			if len(data8) != 32 {
				return nil, fmt.Errorf("failed to read %q: error at line %d: invalid length", path, lineNum)
			}
			identities = append(identities, data8)
			continue
		}
		return nil, fmt.Errorf("failed to read %q: error at line %d: unknown identity type", path, lineNum)
	}
	return identities, nil
}
func decodeArmor(data []byte) ([]byte, error) {
	s := string(data)
	lines := strings.Split(s, "\n")
	var b64Lines []string
	inBody := false
	for _, line := range lines {
		if strings.Contains(line, "BEGIN AGE ENCRYPTED FILE") {
			inBody = true
			continue
		}
		if strings.Contains(line, "END AGE ENCRYPTED FILE") {
			break
		}
		if inBody {
			b64Lines = append(b64Lines, strings.TrimSpace(line))
		}
	}
	if !inBody {
		return nil, fmt.Errorf("failed to parse armor")
	}
	b64Str := strings.Join(b64Lines, "")
	decoded, err := base64.StdEncoding.DecodeString(b64Str)
	if err != nil {
		decoded, err = base64.RawStdEncoding.DecodeString(b64Str)
		if err != nil {
			return nil, err
		}
	}
	return decoded, nil
}
func encodeArmor(data []byte) []byte {
	var buf bytes.Buffer
	buf.WriteString("-----BEGIN AGE ENCRYPTED FILE-----\n")
	b64Str := base64.StdEncoding.EncodeToString(data)
	for i := 0; i < len(b64Str); i += 64 {
		end := i + 64
		if end > len(b64Str) {
			end = len(b64Str)
		}
		buf.WriteString(b64Str[i:end] + "\n")
	}
	buf.WriteString("-----END AGE ENCRYPTED FILE-----\n")
	return buf.Bytes()
}
func readPassphrase(prompt string, confirm bool) (string, error) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return "", fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %v", err)
	}
	defer tty.Close()
	fmt.Fprintf(os.Stderr, "%s", prompt)
	reader := bufio.NewReader(tty)
	pass, err := reader.ReadString('\n')
	if err != nil {
		return "", err
	}
	pass = strings.TrimRight(pass, "\r\n")
	if confirm {
		fmt.Fprintf(os.Stderr, "Confirm passphrase: ")
		confirmPass, err := reader.ReadString('\n')
		if err != nil {
			return "", err
		}
		confirmPass = strings.TrimRight(confirmPass, "\r\n")
		if pass != confirmPass {
			return "", fmt.Errorf("passphrases didn't match")
		}
	}
	if pass == "" {
		words := []string{"release", "response", "step", "brand", "wrap", "ankle", "pair", "unusual", "sword", "train"}
		var gen []string
		for i := 0; i < 10; i++ {
			b := make([]byte, 1)
			rand.Read(b)
			gen = append(gen, words[int(b[0])%len(words)])
		}
		pass = strings.Join(gen, "-")
		fmt.Fprintf(os.Stderr, "Using the autogenerated passphrase %q.\n", pass)
	}
	return pass, nil
}
func encryptStream(plaintext, key []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	var out []byte
	counter := 0
	for len(plaintext) > 0 {
		chunkSize := 64 * 1024
		if len(plaintext) < chunkSize {
			chunkSize = len(plaintext)
		}
		chunk := plaintext[:chunkSize]
		plaintext = plaintext[chunkSize:]
		nonce := make([]byte, 12)
		binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
		ct := aead.Seal(nil, nonce, chunk, nil)
		out = append(out, ct...)
		counter++
	}
	nonce := make([]byte, 12)
	binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
	nonce[11] = 1
	ct := aead.Seal(nil, nonce, []byte{}, nil)
	out = append(out, ct...)
	return out, nil
}
func decryptStream(payloadCT, key []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	var out []byte
	counter := 0
	pos := 0
	for {
		remaining := len(payloadCT) - pos
		if remaining == 0 {
			break
		}
		var chunkLen int
		if remaining > 64*1024+16 {
			chunkLen = 64*1024 + 16
		} else {
			if remaining > 16 {
				candidateLen := remaining - 16
				nonce0 := make([]byte, 12)
				binary.BigEndian.PutUint64(nonce0[3:11], uint64(counter))
				pt0, err0 := aead.Open(nil, nonce0, payloadCT[pos:pos+candidateLen], nil)
				if err0 == nil {
					nonce1 := make([]byte, 12)
					binary.BigEndian.PutUint64(nonce1[3:11], uint64(counter+1))
					nonce1[11] = 1
					pt1, err1 := aead.Open(nil, nonce1, payloadCT[pos+candidateLen:], nil)
					if err1 == nil {
						out = append(out, pt0...)
						out = append(out, pt1...)
						break
					}
				}
			}
			nonce := make([]byte, 12)
			binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
			nonce[11] = 1
			pt, err := aead.Open(nil, nonce, payloadCT[pos:], nil)
			if err == nil {
				out = append(out, pt...)
				break
			}
			nonce[11] = 0
			pt, err = aead.Open(nil, nonce, payloadCT[pos:], nil)
			if err == nil {
				out = append(out, pt...)
				break
			}
			return nil, fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
		nonce := make([]byte, 12)
		binary.BigEndian.PutUint64(nonce[3:11], uint64(counter))
		pt, err := aead.Open(nil, nonce, payloadCT[pos:pos+chunkLen], nil)
		if err != nil {
			return nil, fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
		out = append(out, pt...)
		pos += chunkLen
		counter++
	}
	return out, nil
}
func decryptWithIdentities(data []byte, identities [][]byte) ([]byte, error) {
	idx := bytes.Index(data, []byte("\n--- "))
	if idx == -1 {
		if bytes.HasPrefix(data, []byte("age-encryption.org/v1\n")) {
			return nil, fmt.Errorf("failed to read header: parsing age header: failed to read header: EOF")
		}
		return nil, fmt.Errorf("failed to read header: parsing age header: unexpected intro: %q", string(data[:min(100,len(data))]))
	}
	macEnd := bytes.Index(data[idx+1:], []byte("\n"))
	if macEnd == -1 {
		return nil, fmt.Errorf("failed to read header: parsing age header: failed to read header: EOF")
	}
	macEnd += idx + 1
	headerPart := data[:macEnd]
	lines := bytes.Split(headerPart, []byte("\n"))
	type stanza struct {
		typ  string
		args []string
		body []byte
	}
	var stanzas []stanza
	var cur *stanza
	for _, l := range lines {
		if bytes.HasPrefix(l, []byte("-> ")) {
			if cur != nil {
				stanzas = append(stanzas, *cur)
			}
			parts := strings.Fields(string(l))
			if len(parts) < 2 {
				continue
			}
			cur = &stanza{typ: parts[1], args: parts[2:]}
		} else if cur != nil {
			b, err := base64.RawStdEncoding.DecodeString(string(l))
			if err != nil {
				b, _ = base64.StdEncoding.DecodeString(string(l))
			}
			cur.body = append(cur.body, b...)
		}
	}
	if cur != nil {
		stanzas = append(stanzas, *cur)
	}
	var fileKey []byte
	for _, s := range stanzas {
		if s.typ == "X25519" {
			if len(s.args) < 1 {
				continue
			}
			ephPub, err := base64.RawStdEncoding.DecodeString(s.args[0])
			if err != nil {
				continue
			}
			for _, priv := range identities {
				shared, err := curve25519.X25519(priv, ephPub)
				if err != nil {
					continue
				}
				recPub, _ := curve25519.X25519(priv, curve25519.Basepoint)
				salt := append(ephPub, recPub...)
				prk := hkdfExtract(salt, shared)
				encKey := hkdfExpand(prk, []byte("age-encryption.org/v1/X25519"), 32)
				aead, _ := chacha20poly1305.New(encKey)
				fk, err := aead.Open(nil, make([]byte,12), s.body, nil)
				if err == nil {
					fileKey = fk
					break
				}
			}
		}
		if fileKey != nil {
			break
		}
	}
	if fileKey == nil {
		return nil, fmt.Errorf("no identity matched any of the recipients")
	}
	hdr := data[:idx+4]
	prk := hkdfExtract(nil, fileKey)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write(hdr)
	calcMac := mac.Sum(nil)
	macLine := data[idx+1 : macEnd]
	macB64 := string(macLine[4:])
	expectedMac, _ := base64.RawStdEncoding.DecodeString(macB64)
	if !hmac.Equal(calcMac, expectedMac) {
		return nil, fmt.Errorf("bad header MAC")
	}
	payloadCT := data[macEnd+1:]
	prkPayload := hkdfExtract(nil, fileKey)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	return decryptStream(payloadCT, payloadKey)
}
func encryptFileToRecipients(plaintext []byte, recipients []interface{}) ([]byte, error) {
	fk := make([]byte, 16)
	rand.Read(fk)
	var stanzas []string
	for _, rec := range recipients {
		switch r := rec.(type) {
		case x25519Recipient:
			ephPriv := make([]byte, 32)
			rand.Read(ephPriv)
			ephPub, _ := curve25519.X25519(ephPriv, curve25519.Basepoint)
			shared, _ := curve25519.X25519(ephPriv, r.pub)
			salt := append(ephPub, r.pub...)
			prk := hkdfExtract(salt, shared)
			encKey := hkdfExpand(prk, []byte("age-encryption.org/v1/X25519"), 32)
			aead, _ := chacha20poly1305.New(encKey)
			wrapped := aead.Seal(nil, make([]byte,12), fk, nil)
			stanza := fmt.Sprintf("-> X25519 %s\n%s\n", base64.RawStdEncoding.EncodeToString(ephPub), base64.RawStdEncoding.EncodeToString(wrapped))
			stanzas = append(stanzas, stanza)
		default:
			return nil, fmt.Errorf("unsupported recipient")
		}
	}
	var header bytes.Buffer
	header.WriteString("age-encryption.org/v1\n")
	for _, s := range stanzas {
		header.WriteString(s)
	}
	headerNoMac := header.String() + "---"
	prk := hkdfExtract(nil, fk)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write([]byte(headerNoMac))
	macSum := mac.Sum(nil)
	header.WriteString("--- " + base64.RawStdEncoding.EncodeToString(macSum) + "\n")
	prkPayload := hkdfExtract(nil, fk)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	ct, err := encryptStream(plaintext, payloadKey)
	if err != nil {
		return nil, err
	}
	return append(header.Bytes(), ct...), nil
}
func encryptFileWithPassphrase(plaintext []byte, passphrase string) ([]byte, error) {
	salt := make([]byte, 16)
	rand.Read(salt)
	logN := 18
	scryptKey, err := scrypt.Key([]byte(passphrase), salt, 1<<logN, 8, 1, 32)
	if err != nil {
		return nil, err
	}
	fk := make([]byte, 16)
	rand.Read(fk)
	aead, _ := chacha20poly1305.New(scryptKey)
	wrapped := aead.Seal(nil, make([]byte,12), fk, nil)
	var header bytes.Buffer
	header.WriteString("age-encryption.org/v1\n")
	header.WriteString(fmt.Sprintf("-> scrypt %s %d\n", base64.RawStdEncoding.EncodeToString(salt), logN))
	header.WriteString(base64.RawStdEncoding.EncodeToString(wrapped) + "\n")
	headerNoMac := header.String() + "---"
	prk := hkdfExtract(nil, fk)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write([]byte(headerNoMac))
	macSum := mac.Sum(nil)
	header.WriteString("--- " + base64.RawStdEncoding.EncodeToString(macSum) + "\n")
	prkPayload := hkdfExtract(nil, fk)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	ct, err := encryptStream(plaintext, payloadKey)
	if err != nil {
		return nil, err
	}
	return append(header.Bytes(), ct...), nil
}
func decryptFileWithPassphrase(data []byte, passphrase string) ([]byte, error) {
	idx := bytes.Index(data, []byte("\n--- "))
	if idx == -1 {
		return nil, fmt.Errorf("failed to read header: parsing age header: failed to read header: EOF")
	}
	macEnd := bytes.Index(data[idx+1:], []byte("\n"))
	if macEnd == -1 {
		return nil, fmt.Errorf("failed to read header")
	}
	macEnd += idx + 1
	lines := bytes.Split(data[:macEnd], []byte("\n"))
	var saltB64, wrappedB64 string
	var logN int
	for _, l := range lines {
		if bytes.HasPrefix(l, []byte("-> scrypt ")) {
			parts := bytes.Split(l, []byte(" "))
			if len(parts) >= 4 {
				saltB64 = string(parts[2])
				fmt.Sscanf(string(parts[3]), "%d", &logN)
			}
		} else if saltB64 != "" && wrappedB64 == "" && !bytes.HasPrefix(l, []byte("---")) && !bytes.HasPrefix(l, []byte("age-encryption")) {
			wrappedB64 = string(l)
		}
	}
	if saltB64 == "" {
		return nil, fmt.Errorf("not scrypt")
	}
	salt, _ := base64.RawStdEncoding.DecodeString(saltB64)
	scryptKey, err := scrypt.Key([]byte(passphrase), salt, 1<<logN, 8, 1, 32)
	if err != nil {
		return nil, err
	}
	wrapped, _ := base64.RawStdEncoding.DecodeString(wrappedB64)
	aead, _ := chacha20poly1305.New(scryptKey)
	fk, err := aead.Open(nil, make([]byte,12), wrapped, nil)
	if err != nil {
		return nil, fmt.Errorf("incorrect passphrase")
	}
	hdr := data[:idx+4]
	prk := hkdfExtract(nil, fk)
	headerKey := hkdfExpand(prk, []byte("header"), 32)
	mac := hmac.New(sha256.New, headerKey)
	mac.Write(hdr)
	calcMac := mac.Sum(nil)
	macLine := data[idx+1 : macEnd]
	macB64 := string(macLine[4:])
	expectedMac, _ := base64.RawStdEncoding.DecodeString(macB64)
	if !hmac.Equal(calcMac, expectedMac) {
		return nil, fmt.Errorf("bad header MAC")
	}
	payloadCT := data[macEnd+1:]
	prkPayload := hkdfExtract(nil, fk)
	payloadKey := hkdfExpand(prkPayload, []byte("payload"), 32)
	return decryptStream(payloadCT, payloadKey)
}
func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
