				fmt.Fprintf(os.Stderr, "age: hint: did you mean to use -a/--armor?\n")
				fmt.Fprintf(os.Stderr, "age: hint: force anyway with \"-o -\"\n")
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
		}
	}
	var recipients []interface{}
	for _, recStr := range recipientStrs {
		rec, err := parseRecipient(recStr)
		if err != nil {
			if strings.Contains(err.Error(), "plugin") {
				fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
				lower := strings.ToLower(recStr)
				pluginName := "unknown"
				if idx := strings.Index(lower, "1"); idx != -1 {
					if idx2 := strings.Index(lower[idx+1:], "1"); idx2 != -1 {
						pluginName = lower[idx+1 : idx+1+idx2]
					}
				}
				fmt.Fprintf(os.Stderr, "age: hint: you might want to install the %q plugin\n", pluginName)
				fmt.Fprintf(os.Stderr, "age: hint: visit https://age-encryption.org/awesome#plugins for a list of available plugins\n")
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		recipients = append(recipients, rec)
	}
	for _, rf := range recipientsFiles {
		recs, err := readRecipientsFile(rf)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		recipients = append(recipients, recs...)
	}
	// Handle -e -i
	if encryptExplicit && len(identityPaths) > 0 {
		for _, idPath := range identityPaths {
			ids, err := parseIdentityFile(idPath)
			if err != nil {
				fmt.Fprintf(os.Stderr, "age: error: reading %q: %v\n", idPath, err)
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
			for _, priv := range ids {
				pub, _ := curve25519.X25519(priv, curve25519.Basepoint)
				recipients = append(recipients, x25519Recipient{pub: pub})
			}
		}
	}
	var inputData []byte
	var err error
	if inputPath == "" || inputPath == "-" {
		inputData, err = io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			os.Exit(1)
		}
	} else {
		inputData, err = os.ReadFile(inputPath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: failed to open input file %q: open %s: no such file or directory\n", inputPath, inputPath)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
	}
	if decryptFlag {
		isArmor := bytes.Contains(inputData, []byte("BEGIN AGE ENCRYPTED FILE"))
		var rawData []byte
		if isArmor {
			rawData, err = decodeArmor(inputData)
			if err != nil {
				fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
				os.Exit(1)
			}
		} else {
			rawData = inputData
		}
		if bytes.Contains(rawData, []byte("-> scrypt ")) {
			if len(identityPaths) > 0 {
				fmt.Fprintf(os.Stderr, "age: error: file is passphrase-encrypted but identities were specified with -i/--identity or -j\n")
				fmt.Fprintf(os.Stderr, "age: hint: remove all -i/--identity/-j flags to decrypt passphrase-encrypted files\n")
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
			var pass string
			if term.IsTerminal(int(os.Stdin.Fd())) {
				fmt.Fprintf(os.Stderr, "Enter passphrase: ")
				reader := bufio.NewReader(os.Stdin)
				passLine, _ := reader.ReadString('\n')
				passLine = strings.TrimRight(passLine, "\r\n")
				pass = passLine
			} else {
				tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
				if err != nil {
					fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
					os.Exit(1)
				}
				fmt.Fprintf(os.Stderr, "Enter passphrase: ")
				reader := bufio.NewReader(tty)
				passLine, _ := reader.ReadString('\n')
				passLine = strings.TrimRight(passLine, "\r\n")
				tty.Close()
				pass = passLine
			}
			plain, err := decryptFileWithPassphrase(rawData, pass)
			if err != nil {
				fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
			if outputPath == "" || outputPath == "-" {
				os.Stdout.Write(plain)
			} else {
				os.WriteFile(outputPath, plain, 0644)
			}
			os.Exit(0)
		}
		if len(identityPaths) == 0 {
			fmt.Fprintf(os.Stderr, "age: error: the file is not passphrase-encrypted, identities are required\n")
			fmt.Fprintf(os.Stderr, "age: hint: specify identities with -i/--identity or -j to decrypt this file\n")
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		var idGroups [][]byte
		for _, idPath := range identityPaths {
			ids, err := parseIdentityFile(idPath)
			if err != nil {
				fmt.Fprintf(os.Stderr, "age: error: reading %q: %v\n", idPath, err)
				fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
				os.Exit(1)
			}
			idGroups = append(idGroups, ids...)
		}
		plain, err := decryptWithIdentities(rawData, idGroups)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		if outputPath == "" || outputPath == "-" {
			os.Stdout.Write(plain)
		} else {
			os.WriteFile(outputPath, plain, 0644)
		}
		os.Exit(0)
	} else {
		if passphraseFlag {
			pass, err := readPassphrase("Enter passphrase (leave empty to autogenerate a secure one): ", true)
			if err != nil {
				fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
				os.Exit(1)
			}
			enc, err := encryptFileWithPassphrase(inputData, pass)
			if err != nil {
				fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
				os.Exit(1)
			}
			var outData []byte
			if armorFlag {
				outData = encodeArmor(enc)
			} else {
				outData = enc
			}
			if outputPath == "" || outputPath == "-" {
				os.Stdout.Write(outData)
			} else {
				os.WriteFile(outputPath, outData, 0644)
			}
			os.Exit(0)
		}
		enc, err := encryptFileToRecipients(inputData, recipients)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}
		var outData []byte
		if armorFlag {
			outData = encodeArmor(enc)
		} else {
			outData = enc
		}
		if outputPath == "" || outputPath == "-" {
			os.Stdout.Write(outData)
		} else {
			os.WriteFile(outputPath, outData, 0644)
		}
		os.Exit(0)
	}
}
